FROM schedule_attendance sa
WHERE sa.user_key    = #{userKey}
  AND sa.is_latest   = 1
  AND sa.schedule_id IN

      #{id}

SELECT sa.*, u.nickname AS display_name FROM schedule_attendance sa JOIN `user` u ON u.user_key = sa.user_key JOIN group_schedule gs ON gs.schedule_id = sa.schedule_id WHERE gs.group_id = #{groupId} AND sa.is_latest = 1 AND sa.status IN ('CONFIRMED', 'PENDING') AND sa.schedule_id IN
#{id}
ORDER BY sa.schedule_id, sa.created_at ASC

